// L Compute PTX back end (step 4): translates the IR to PTX text (NVIDIA's public virtual ISA). ptxas / the driver JIT turn PTX into machine code; nothing here is reverse engineered.
// ABI of the generated entry point: for each kernel parameter, in order: a buffer is TWO parameters (u64 pointer, s32 length in floats), an i32 or f32 scalar is one parameter; the last parameter is a u64 pointer to one u32 "error word" (0 = no error).
// Checked access: every global and shared access is bounds checked; a failing access is skipped and its instruction number + 1 is written to the error word. Integer division by zero is also reported (and made harmless).
// Float arithmetic uses explicit round-to-nearest (.rn) so ptxas does not fuse a multiply and an add: results equal the interpreter bit for bit (except exp and tanh, which PTX only offers as approximations).
// Not detectable on a GPU: barrier divergence (undefined behaviour in hardware); that check stays in the CPU back ends.
use crate::ir::*;
use std::fmt::Write;

fn n(k: &Kernel, r: Reg) -> String { match k.regs[r.0 as usize] { Ty::I32 => format!("%r{}", r.0), Ty::F32 => format!("%f{}", r.0), Ty::Pred => format!("%p{}", r.0) } }
fn cmpname(c: CmpOp) -> &'static str { match c { CmpOp::Lt => "lt", CmpOp::Le => "le", CmpOp::Gt => "gt", CmpOp::Ge => "ge", CmpOp::Eq => "eq", CmpOp::Ne => "ne" } }

pub fn to_ptx(k: &Kernel) -> String {
    let mut s = String::new(); let nr = k.regs.len().max(1);
    writeln!(s, "// generated by L Compute (ptx.rs) from kernel {}\n.version 7.1\n.target sm_75\n.address_size 64\n", k.name).unwrap();
    for (a, &len) in k.shared.iter().enumerate() { writeln!(s, ".shared .align 4 .f32 sh{}[{}];", a, len.max(1)).unwrap(); }
    write!(s, ".visible .entry {}(\n", k.name).unwrap();
    for (i, p) in k.params.iter().enumerate() { match p { ParamKind::BufF32 => write!(s, "    .param .u64 a{}p,\n    .param .s32 a{}n,\n", i, i).unwrap(), ParamKind::I32 => write!(s, "    .param .s32 a{},\n", i).unwrap(), ParamKind::F32 => write!(s, "    .param .f32 a{},\n", i).unwrap() } }
    writeln!(s, "    .param .u64 aerr\n)\n{{").unwrap();
    writeln!(s, "    .reg .s32 %r<{nr}>;\n    .reg .f32 %f<{nr}>;\n    .reg .pred %p<{nr}>;\n    .reg .pred %bad;\n    .reg .u32 %u<4>;\n    .reg .s32 %s0;\n    .reg .u64 %rd<4>;\n    .reg .u64 %perr;").unwrap();
    for (i, p) in k.params.iter().enumerate() { if *p == ParamKind::BufF32 { writeln!(s, "    .reg .u64 %bp{i};\n    .reg .s32 %bn{i};\n    ld.param.u64 %bp{i}, [a{i}p];\n    cvta.to.global.u64 %bp{i}, %bp{i};\n    ld.param.s32 %bn{i}, [a{i}n];", i = i).unwrap(); } }
    writeln!(s, "    ld.param.u64 %perr, [aerr];\n    cvta.to.global.u64 %perr, %perr;").unwrap();
    for (pc, ins) in k.code.iter().enumerate() {
        let code = pc + 1; let o = &mut s;
        match ins {
            Inst::ConstI(d, v) => writeln!(o, "    mov.s32 {}, {};", n(k, *d), v),
            Inst::ConstF(d, v) => writeln!(o, "    mov.f32 {}, 0f{:08X};", n(k, *d), v.to_bits()),
            Inst::Special(d, sp) => { let (reg, ax) = match sp { Sp::Tid(a) => ("tid", *a), Sp::Bid(a) => ("ctaid", *a), Sp::Bdim(a) => ("ntid", *a), Sp::Gdim(a) => ("nctaid", *a) }; let c = ['x', 'y', 'z'][ax as usize];
                writeln!(o, "    mov.u32 %u0, %{}.{};\n    mov.b32 {}, %u0;", reg, c, n(k, *d)) }
            Inst::ParamS(d, p) => match k.params[*p as usize] { ParamKind::I32 => writeln!(o, "    ld.param.s32 {}, [a{}];", n(k, *d), p), ParamKind::F32 => writeln!(o, "    ld.param.f32 {}, [a{}];", n(k, *d), p), ParamKind::BufF32 => panic!("buffer used as scalar") },
            Inst::Mov(d, a) => writeln!(o, "    mov.{} {}, {};", match k.regs[d.0 as usize] { Ty::I32 => "s32", Ty::F32 => "f32", Ty::Pred => "pred" }, n(k, *d), n(k, *a)),
            Inst::Fma(d, a, b, c) => writeln!(o, "    fma.rn.f32 {}, {}, {}, {};", n(k, *d), n(k, *a), n(k, *b), n(k, *c)),
            Inst::AddImm(d, a, c) => writeln!(o, "    add.s32 {}, {}, {};", n(k, *d), n(k, *a), c),
            Inst::BinI(d, op, a, b) => { let (dn, an, bn) = (n(k, *d), n(k, *a), n(k, *b));
                if k.regs[d.0 as usize] == Ty::Pred { match op { BinOp::And => writeln!(o, "    and.pred {}, {}, {};", dn, an, bn), BinOp::Or => writeln!(o, "    or.pred {}, {}, {};", dn, an, bn), _ => panic!("operator {:?} on predicates", op) } }
                else { match op {
                    BinOp::Add => writeln!(o, "    add.s32 {}, {}, {};", dn, an, bn), BinOp::Sub => writeln!(o, "    sub.s32 {}, {}, {};", dn, an, bn), BinOp::Mul => writeln!(o, "    mul.lo.s32 {}, {}, {};", dn, an, bn),
                    BinOp::Min => writeln!(o, "    min.s32 {}, {}, {};", dn, an, bn), BinOp::Max => writeln!(o, "    max.s32 {}, {}, {};", dn, an, bn),
                    BinOp::And => writeln!(o, "    and.b32 {}, {}, {};", dn, an, bn), BinOp::Or => writeln!(o, "    or.b32 {}, {}, {};", dn, an, bn),
                    BinOp::Shl => writeln!(o, "    and.b32 %u0, {}, 31;\n    shl.b32 {}, {}, %u0;", bn, dn, an), BinOp::Shr => writeln!(o, "    and.b32 %u0, {}, 31;\n    shr.s32 {}, {}, %u0;", bn, dn, an),
                    BinOp::Div | BinOp::Rem => writeln!(o, "    setp.eq.s32 %bad, {b}, 0;\n    @%bad st.global.u32 [%perr], {c};\n    selp.s32 %s0, 1, {b}, %bad;\n    {i}.s32 {d}, {a}, %s0;", b = bn, c = code, i = if *op == BinOp::Div { "div" } else { "rem" }, d = dn, a = an) } } }
            Inst::BinF(d, op, a, b) => { let (dn, an, bn) = (n(k, *d), n(k, *a), n(k, *b)); match op {
                BinOp::Add => writeln!(o, "    add.rn.f32 {}, {}, {};", dn, an, bn), BinOp::Sub => writeln!(o, "    sub.rn.f32 {}, {}, {};", dn, an, bn), BinOp::Mul => writeln!(o, "    mul.rn.f32 {}, {}, {};", dn, an, bn),
                BinOp::Div => writeln!(o, "    div.rn.f32 {}, {}, {};", dn, an, bn), BinOp::Min => writeln!(o, "    min.f32 {}, {}, {};", dn, an, bn), BinOp::Max => writeln!(o, "    max.f32 {}, {}, {};", dn, an, bn),
                _ => panic!("operator {:?} on floats", op) } }
            Inst::CmpI(d, c, a, b) => writeln!(o, "    setp.{}.s32 {}, {}, {};", cmpname(*c), n(k, *d), n(k, *a), n(k, *b)),
            Inst::CmpF(d, c, a, b) => writeln!(o, "    setp.{}.f32 {}, {}, {};", if *c == CmpOp::Ne { "neu" } else { cmpname(*c) }, n(k, *d), n(k, *a), n(k, *b)),
            Inst::UnF(d, op, a) => { let (dn, an) = (n(k, *d), n(k, *a)); match op { UnOp::Neg => writeln!(o, "    neg.f32 {}, {};", dn, an), UnOp::Abs => writeln!(o, "    abs.f32 {}, {};", dn, an), UnOp::Sqrt => writeln!(o, "    sqrt.rn.f32 {}, {};", dn, an),
                UnOp::Exp => writeln!(o, "    mul.f32 {d}, {a}, 0f3FB8AA3B;\n    ex2.approx.f32 {d}, {d};", d = dn, a = an), UnOp::Tanh => writeln!(o, "    tanh.approx.f32 {}, {};", dn, an) } }
            Inst::CvtIF(d, a) => writeln!(o, "    cvt.rn.f32.s32 {}, {};", n(k, *d), n(k, *a)), Inst::CvtFI(d, a) => writeln!(o, "    cvt.rzi.s32.f32 {}, {};", n(k, *d), n(k, *a)),
            Inst::SelF(d, p, a, b) => writeln!(o, "    selp.f32 {}, {}, {}, {};", n(k, *d), n(k, *a), n(k, *b), n(k, *p)),
            Inst::LdG(d, b, i) => writeln!(o, "    mov.b32 %u0, {i};\n    setp.ge.u32 %bad, %u0, %bn{b};\n    @%bad st.global.u32 [%perr], {c};\n    @%bad mov.f32 {d}, 0f00000000;\n    mul.wide.u32 %rd0, %u0, 4;\n    add.u64 %rd0, %bp{b}, %rd0;\n    @!%bad ld.global.f32 {d}, [%rd0];", i = n(k, *i), b = b, c = code, d = n(k, *d)),
            Inst::StG(b, i, v) => writeln!(o, "    mov.b32 %u0, {i};\n    setp.ge.u32 %bad, %u0, %bn{b};\n    @%bad st.global.u32 [%perr], {c};\n    mul.wide.u32 %rd0, %u0, 4;\n    add.u64 %rd0, %bp{b}, %rd0;\n    @!%bad st.global.f32 [%rd0], {v};", i = n(k, *i), b = b, c = code, v = n(k, *v)),
            Inst::LdS(d, a, i) => writeln!(o, "    mov.b32 %u0, {i};\n    setp.ge.u32 %bad, %u0, {len};\n    @%bad st.global.u32 [%perr], {c};\n    @%bad mov.f32 {d}, 0f00000000;\n    mul.wide.u32 %rd0, %u0, 4;\n    mov.u64 %rd1, sh{a};\n    add.u64 %rd0, %rd1, %rd0;\n    @!%bad ld.shared.f32 {d}, [%rd0];", i = n(k, *i), a = a, len = k.shared[*a as usize], c = code, d = n(k, *d)),
            Inst::StS(a, i, v) => writeln!(o, "    mov.b32 %u0, {i};\n    setp.ge.u32 %bad, %u0, {len};\n    @%bad st.global.u32 [%perr], {c};\n    mul.wide.u32 %rd0, %u0, 4;\n    mov.u64 %rd1, sh{a};\n    add.u64 %rd0, %rd1, %rd0;\n    @!%bad st.shared.f32 [%rd0], {v};", i = n(k, *i), a = a, len = k.shared[*a as usize], c = code, v = n(k, *v)),
            Inst::Barrier => writeln!(o, "    bar.sync 0;"), Inst::Label(l) => writeln!(o, "L{}:", l), Inst::Br(l) => writeln!(o, "    bra L{};", l),
            Inst::BrIf(p, l) => writeln!(o, "    @{} bra L{};", n(k, *p), l), Inst::BrIfNot(p, l) => writeln!(o, "    @!{} bra L{};", n(k, *p), l), Inst::Ret => writeln!(o, "    ret;"),
        }.unwrap();
    }
    writeln!(s, "    ret;\n}}").unwrap(); s
}
